window.safeStorage={set:function(e,t){try{localStorage.setItem(e,String(t))}catch(e){console.warn("Storage set failed",e)}},get:function(e){try{return localStorage.getItem(e)}catch(e){return null}},remove:function(e){try{localStorage.removeItem(e)}catch(e){console.warn("Storage remove failed",e)}}},window.throttleRAF||(window.throttleRAF=function(e){var t,r,n=!1;return function(){t=arguments,r=this,n||(n=!0,requestAnimationFrame(function(){try{e.apply(r,t)}finally{n=!1}}))}}),window.safeParseDate=function(e){if(!e)return new Date("Invalid Date");if(e instanceof Date)return new Date(e.getTime());if("number"==typeof e)return new Date(e>9999999999?e:1e3*e);if("string"==typeof e&&/^\d+$/.test(e.trim())){var t=parseInt(e.trim(),10);return new Date(t>9999999999?t:1e3*t)}var r=String(e).trim(),n=new Date(r);if(!isNaN(n.getTime()))return n;if(/Z|[+-]\d{2}:\d{2}$/i.test(r))return n=new Date(r.replace(/-/g,"/"));var a=r.replace(/-/g,"/").replace("T"," ").replace(/\.\d+/,"");return n=new Date(a)};
